/** Register/refresh the bounded default, then apply governor + rolling-window gates. */
export async function preflightDreamCycle(
  sql: Sql,
  input: { workspaceId: string; potSlug: string; config?: Partial<DreamCycleConfig> },
  deps: DreamGovernorDeps = defaultDeps,
): Promise<DreamGovernorPreflight> {
  const config = resolveDreamCycleConfig(input.config);
  const loopId = dreamLoopId(input.potSlug);
  if (!(await deps.enabled())) {
    return {
      allow: false,
      loopId,
      reason: 'governor-dark',
      cycleRemainingUsd: null,
      rollingSpentUsd: 0,
      rollingRemainingUsd: config.rolling24hCostUsd,
      rollingLoopCount: 0,
    };
  }

  await deps.register(sql, dreamRegistrationInput({ ...input, config }));
  const [cycle, rolling] = await Promise.all([
    deps.check(sql, { workspaceId: input.workspaceId, loopId }),
    deps.sumSince(sql, {
      workspaceId: input.workspaceId,
      sinceMs: deps.now() - DREAM_ROLLING_WINDOW_MS,
    }),
  ]);
  const rollingRemainingUsd = config.rolling24hCostUsd - rolling.totalUsd;
  if (!cycle.allow) {
    return {
      allow: false,
      loopId,
      reason: cycle.reason ?? 'governor-error',
      cycleRemainingUsd: cycle.remainingUsd,
      rollingSpentUsd: rolling.totalUsd,
      rollingRemainingUsd,
      rollingLoopCount: rolling.loopCount,

    });
  });

  it('refuses at the workspace-wide rolling ceiling and measures the exact 24h window', async () => {
    const d = deps({ sumSince: vi.fn(async () => ({ totalUsd: 5, loopCount: 3 })) });

    await expect(preflightDreamCycle(sql, { workspaceId: 'ws-1', potSlug: 'papercusp' }, d)).resolves.toMatchObject({
      allow: false,
      reason: 'rolling-cap-exceeded',
      rollingSpentUsd: 5,
      rollingRemainingUsd: 0,
      rollingLoopCount: 3,
    });
    expect(d.sumSince).toHaveBeenCalledWith(sql, {
      workspaceId: 'ws-1',
      sinceMs: d.now() - DREAM_ROLLING_WINDOW_MS,
    });
  });

  it('returns both cycle and rolling remaining spend when every gate allows', async () => {
    const d = deps();

    await expect(preflightDreamCycle(sql, { workspaceId: 'ws-1', potSlug: 'papercusp' }, d)).resolves.toEqual({
      allow: true,
      loopId: 'dream:papercusp',
      cycleRemainingUsd: 1,
      rollingSpentUsd: 1.25,
      rollingRemainingUsd: 3.75,
      rollingLoopCount: 2,
    });
    expect(d.register).toHaveBeenCalledWith(
      sql,
      expect.objectContaining({ loopId: 'dream:papercusp', budgetKind: 'per-cycle', budgetUsd: 1 }),
    );
  });
});

